public class Demo13 {
public static void main(String[] args) {
int a = 10;
int b;
    b = a++ + a++ + a++;

    System.out.println(a);
    System.out.println(b);
}
}

public class Demo14 {
public static void main(String[] args) {
int a = 10;
int b;
    b = ++a + ++a + ++a;

    System.out.println(a);
    System.out.println(b);
}
}

public class Demo15 {
public static void main(String[] args) {
int a = 10;
int b;
    b = a++ + a++ + a-- + --a;

    System.out.println(a);
    System.out.println(b);
}
}

public class Demo16 {
public static void main(String[] args) {
int a = 10;
int b;
    b = a++ + a++ + --a + --a + a-- + a++ + a-- - a++;

    System.out.println(a);
    System.out.println(b);
}
}

a += b;
a -= b;
a *= b;
a /= b;
a %= b;

int a = 10;
int b = 20;

b -= a;

int a = 10;
int b = 20;

a *= b;

int a = 10;
int b = 20;

b /= a;

